import json, re

fpath = "/home/ubuntu/.claude-account-1/projects/-home-ubuntu--agent-ml-research-idea-gen-0509-17-projects-recovery-aware-struct-prune/d6340ee6-f9f9-4ade-b37f-565650398cf3/tool-results/mcp-agent-ml-research-read_registry-1779394072534.txt"

with open(fpath, 'r') as f:
    raw = f.read()

outer = json.loads(raw)
inner = json.loads(outer['result'])
experiments = inner['data']['experiments']

# Now let me also check: are there any "sft_random" or "random_20" or "random_25" entries?
print("=== EXPERIMENTS WITH 'random' IN EXP_ID ===")
for eid in sorted(experiments.keys()):
    if 'random' in eid.lower():
        exp = experiments[eid]
        print(f"  {eid}: status={exp.get('status')}, conclusion={exp.get('conclusion')}")
        print(f"    hypothesis: {exp.get('hypothesis','')[:200]}")
        spec = exp.get('spec', {})
        if isinstance(spec, dict):
            print(f"    command: {spec.get('command','')[:300]}")
        print(f"    metrics: {json.dumps(exp.get('metrics', {}))}")

# Check for sft_cka_only, sft_standard, sft_rasp at 25%
print("\n=== EXPERIMENTS WITH '25' IN EXP_ID ===")
for eid in sorted(experiments.keys()):
    if '25' in eid:
        exp = experiments[eid]
        print(f"  {eid}: status={exp.get('status')}, conclusion={exp.get('conclusion')}")
        metrics = exp.get('metrics', {})
        if isinstance(metrics, dict):
            acc_keys = {k: v for k, v in metrics.items() if 'accuracy' in k.lower() or 'pass_at' in k.lower() or k == 'accuracy'}
            if acc_keys:
                print(f"    accuracies: {acc_keys}")

# Check for "rasp_25" or "standard_25" (training, not just eval)
print("\n=== EXPERIMENTS MENTIONING 'rasp_25' OR 'standard_25' IN FULL TEXT ===")
for eid, exp in sorted(experiments.items()):
    full = json.dumps(exp) + " " + eid
    if re.search(r'rasp.25|standard.25|cka.only.25', full, re.IGNORECASE):
        if eid not in ['eval_humaneval_sft_standard_25', 'eval_math500_sft_standard_25', 'eval_math500_sft_standard_25_v2', 'grpo_cka_only_25', 'eval_postprune_25']:
            print(f"  {eid}")
            metrics = exp.get('metrics', {})
            if isinstance(metrics, dict):
                for k, v in metrics.items():
                    if 'accuracy' in k.lower() or 'gsm8k' in k.lower() or 'math' in k.lower() or k in ['accuracy']:
                        print(f"    {k}: {v}")

# Look for any unpruned GSM8K experiment
print("\n=== UNPRUNED GSM8K EVAL ===")
for eid, exp in sorted(experiments.items()):
    full = json.dumps(exp) + " " + eid
    if re.search(r'unpruned|dense', full, re.IGNORECASE) and re.search(r'gsm8k', full, re.IGNORECASE):
        print(f"  {eid}: status={exp.get('status')}, conclusion={exp.get('conclusion')}")
        print(f"    metrics: {json.dumps(exp.get('metrics', {}))}")

# Check for "sft_cka_only_25" or "sft_rasp_25" as training experiments
print("\n=== LOOKING FOR SFT/GRPO TRAINING for 25% (not just eval) ===")
for eid, exp in sorted(experiments.items()):
    full = json.dumps(exp) + " " + eid
    if re.search(r'sft.*(rasp|standard|cka).*25|grpo.*(rasp|standard).*25|(rasp|standard|cka).*25.*(sft|grpo)', full, re.IGNORECASE):
        print(f"  {eid}")
        print(f"    status={exp.get('status')}, conclusion={exp.get('conclusion')}")
        hyp = exp.get('hypothesis', '')
        print(f"    hypothesis: {hyp[:200]}")

